// Variáveis globais para armazenar valores calculados
let currentValue = 0;
let pixTotal = 0;
let cardTotal = 0;

// Função chamada ao trocar a opção de pagamento (Radio Button)
function togglePanel(method) {
    // Esconde todos os painéis primeiro
    document.getElementById('panelPix').style.display = 'none';
    document.getElementById('panelCard').style.display = 'none';

    // Mostra o painel correspondente
    if (method === 'pix') {
        document.getElementById('panelPix').style.display = 'block';
    } else if (method === 'card') {
        document.getElementById('panelCard').style.display = 'block';
    }
}

// Função chamada ao clicar em "Informar dados"
function informarDados() {
    const valorInput = document.getElementById('valor');
    const errorMessage = document.getElementById('errorMessage');

    // Limpa mensagens anteriores
    errorMessage.style.display = 'none';
    valorInput.classList.remove('invalid');

    // Validação básica: campo vazio?
    if (valorInput.value.trim() === '') {
        alert("Por favor, preencha o campo Valor antes de continuar.");
        return;
    }

    // Converte string para número
    currentValue = parseFloat(valorInput.value);

    // Lógica de exibição baseada na forma de pagamento selecionada
    const paymentMethod = document.querySelector('input[name="paymentMethod"]:checked').value;

    if (paymentMethod === 'pix') {
        calcularPix();
    } else if (paymentMethod === 'card') {
        mostrarPainelCartao();
    }
}

// --- Lógica do Painel PIX ---
function calcularPix() {
    const discount = 0.10; // 10% de desconto
    pixTotal = currentValue * (1 - discount);

    // Atualiza o texto no painel Pix
    document.getElementById('pixTotal').innerText = formatCurrency(pixTotal);
}

// --- Lógica do Painel Cartão ---
function mostrarPainelCartao() {
    // Reseta estado visual do input de cartão
    const cardInput = document.getElementById('cardNumber');
    cardInput.className = ''; 
    cardInput.value = '';
    document.getElementById('cardTypeIcon').style.opacity = '0';
}

// Validação ao digitar no campo do cartão
function validateCardNumber(value) {
    const input = document.getElementById('cardNumber');
    const iconContainer = document.getElementById('cardTypeIcon');

    // Remove classes anteriores
    input.classList.remove('valid-1234', 'valid-4321', 'invalid');

    // Normaliza o valor (remove espaços se houver)
    const cleanValue = value.replace(/\s/g, '');

    if (cleanValue.length > 0) {
        // Verifica as condições específicas
        if (cleanValue.startsWith('1234')) {
            input.classList.add('valid-1234');
            iconContainer.style.opacity = '1';
            iconContainer.innerHTML = "💳"; // Ícone VISA (exemplo)
        } else if (cleanValue.startsWith('4321')) {
            input.classList.add('valid-4321');
            iconContainer.style.opacity = '1';
            iconContainer.innerHTML = "🏦"; // Ícone Banco/Outro
        } else {
            // Mensagem de erro visual
            input.classList.add('invalid');
            setTimeout(() => {
                input.classList.remove('invalid');
            }, 500);
        }
    }
}

// Cálculo de parcelas e total
function calculateInstallments() {
    const parcels = parseInt(document.getElementById('parcels').value);
    const interestRate = getInterestRate(parcels);

    // Calcula o valor final após juros
    cardTotal = currentValue + (currentValue * interestRate);

    document.getElementById('cardTotal').innerText = formatCurrency(cardTotal);
}

// Retorna a taxa de juros baseada nas parcelas
function getInterestRate(parcels) {
    if (parcels <= 3) return 0; // Sem juros
    if (parcels === 4) return 0.05; // 5%
    if (parcels === 5) return 0.10; // 10%
    return 0;
}

// Processamento final do pagamento
function processPayment() {
    const successMsg = confirm("Deseja confirmar o pagamento?");
    if (successMsg) {
        alert("Pagamento realizado com sucesso!");
        // Aqui você redirecionaria para o gateway real ou limparia o formulário
        location.reload(); 
    }
}

// Utilitário para formatação de moeda
function formatCurrency(value) {
    return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}
